import {careerOpportunities} from './career-opportunities.js';
import {educationRoutesFor,educationRouteGroups} from './education-routes.js';
import {careerTitle,careerEducationSummary} from './career-presentation.js';
import {careerGlyph} from './career-glyph.js';
import {educationTradeoff} from './career-review-logic.js';
import {careerLanguage} from './career-language.js';
import {formatSalary} from './salary-progression.js';
import {escapeHTML as h} from './html.js';
export function educationBadges(o){return '<div class="education-badges" aria-label="Education routes">'+educationRoutesFor(o).map(r=>'<span class="education-badge route-'+r.key+'">'+h(r.label)+'</span>').join('')+'</div>';}
const linkFor=(s,id,informationOnly)=>'#/'+(informationOnly?'learn/career/':s.profileJourney?.started?'journey/profession/':'career/')+id;
function fitText(r,{qualified=false}={}){const b=qualified?r.entry:r.start,meets=qualified?r.meetsQualified:r.meetsAtStart;if(!b)return {key:'neutral',text:'Austin pay estimate'};if(meets)return {key:b.room?'yes':'tight',text:(qualified&&r.firstStage!=='entry'?'After qualification: ':'Starting pay: ')+(b.room?'covers your goal':'covers it, with little spare')};if(b.covers)return {key:'tight',text:'Close to your starting-income goal'};return {key:'short',text:qualified&&r.paidTraining?'Qualified pay falls short':'Starting pay falls short'};}
function alternativeCard(s,r,{informationOnly=false,qualified=false,compareOnly=false}={}){const fit=fitText(r,{qualified}),money=qualified?r.qualifiedPay:r.firstPay;return '<article class="opportunity-card"><header>'+careerGlyph(r.o)+'<h3>'+(compareOnly?'<button class="opportunity-compare" data-preview="'+h(r.id)+'">'+h(careerTitle(r.o))+' →</button>':'<a href="'+linkFor(s,r.id,informationOnly)+'">'+h(careerTitle(r.o))+' →</a>')+'</h3></header>'+educationBadges(r.o)+'<p class="opportunity-pay">'+formatSalary(money)+'<span> / year · before tax'+(qualified?' · qualified entry':'')+'</span></p><p class="opportunity-fit fit-'+fit.key+'">'+h(fit.text)+'</p><p class="opportunity-work">'+h(careerLanguage[r.id]?.[0]||r.o.summary)+'</p><p class="opportunity-scope">'+h(r.scope)+(r.broader?' · broader field':'')+'</p>'+(!compareOnly?'<a class="opportunity-lifestyle" href="#/'+(informationOnly?'learn/':'')+'salary/'+h(r.id)+'/'+h(qualified?'entry':r.firstStage)+(informationOnly?'':'?from=career')+'">'+(informationOnly?'Austin lifestyle example':'See the lifestyle')+' →</a>':'')+(educationTradeoff(s,r.o)?'<p class="opportunity-tradeoff">'+h(educationTradeoff(s,r.o))+'</p>':'')+'<details class="more-info"><summary>More info</summary><p>'+h(r.connection)+'</p><p>'+h(careerEducationSummary(r.o))+'</p>'+r.routes.filter(x=>x.detail).map(x=>'<p>'+h(x.label)+': '+h(x.detail)+'</p>').join('')+(r.interestContrast?'<p>You liked related tasks, but your wider interest pattern differs.</p>':'')+(!r.supported?'<p>This is a different job to explore, not a confirmed match. Compare its daily work before choosing.</p>':'')+(r.paidTraining?'<p>Paid training: '+formatSalary(r.paidTraining.amount)+' / year · '+h(r.paidTraining.label)+'. Required study may come before that paid stage.</p>':'')+(r.later?'<p>'+h(r.later.label)+' illustration: '+formatSalary(r.later.amount)+' / year could cover this budget. This is a planning scenario, not a promised raise.</p>':'')+(r.requiresExperience?'<p>This is a later-career role. Related experience comes before the pay shown.</p>':'')+'<p>Pay is an estimate, not a job offer. Training costs, aid and loan payments have their own budget on the job page.</p></details></article>';}
function routeRow(s,g,options){return '<details class="education-route-row route-'+g.id+'"'+(g.id==='college'&&g.rows.length?' open':'')+'><summary><span>'+h(g.title)+'</span>'+(g.rows.length?'<span class="route-preview">'+g.rows.map(r=>h(careerTitle(r.o))+' · '+formatSalary(r.qualifiedPay)).join(' / ')+'</span>':'')+'</summary><p>'+h(g.copy)+'</p>'+(g.rows.length?'<div class="opportunity-grid">'+g.rows.map(r=>alternativeCard(s,r,{...options,qualified:true})).join('')+'</div>':'<p class="route-context">The related options shown here use other routes. This route is still available in other career fields.</p><a href="#/learn/'+(['work','apprenticeship','program'].includes(g.id)?'training':'college')+'">Read about other careers →</a>')+'</details>';}
export function opportunitiesPanel(s,{anchorId=s.guide?.primaryCareer||'',compact=false,informationOnly=false,compareOnly=false}={}){const p=careerOpportunities(s,{anchorId}),anchor=p.rows.find(r=>r.anchor);if(!p.rows.length)return '';const needHelp=p.hasLifestyle&&(!anchor||!anchor.meetsAtStart),now=p.funded,after=p.afterTraining,show=now.length?now:after;
 const degreeRoutes=p.collegeOptions.filter(r=>r.meetsQualified&&!r.requiresExperience);const compare=(p.later.length?p.later:p.rows.filter(r=>!r.anchor&&!r.requiresExperience)).slice(0,3);
 const goal=p.hasLifestyle&&p.goal?'<p class="opportunity-goal"><strong>Your Austin income goal</strong> '+formatSalary(p.goal.low)+'–'+formatSalary(p.goal.high)+' / year before tax</p>':'';
 const alternatives=p.hasLifestyle?(show.length?'<h3>'+(now.length?'Related options that can cover your goal':'Related options that can cover it after qualifying')+'</h3><p>'+(needHelp?'Keep your original interest. Compare these nearby options too.':'Your goal fits. Here are other related options to compare.')+'</p><div class="opportunity-grid">'+show.map(r=>alternativeCard(s,r,{informationOnly,qualified:!now.length,compareOnly})).join('')+'</div>':compare.length?'<h3>Keep the interest. Compare the pay.</h3><p>These options fall short at the start. More info shows any later-pay scenario that could cover your goal. Higher pay is not guaranteed.</p><div class="opportunity-grid">'+compare.map(r=>alternativeCard(s,r,{informationOnly,qualified:true,compareOnly})).join('')+'</div>':''):'';
 const tiers='<h3>What each education route could open</h3><p>These are different jobs—not automatic promotions or a guaranteed pay increase.</p><div class="education-route-list">'+p.groups.map(g=>routeRow(s,g,{informationOnly,compareOnly})).join('')+'</div>';
 const college=degreeRoutes.length?'<p class="college-opportunity-note"><strong>A college degree could open more options here.</strong> Compare the work, time and cost of '+degreeRoutes.slice(0,2).map(r=>h(careerTitle(r.o))).join(' and ')+'.</p>':'<p class="college-opportunity-note"><strong>Keep a degree route in the picture.</strong> College can build skills and open other roles. Compare the specific programs and work you want.</p>';
 return '<section class="career-opportunities" data-opportunity-version="'+p.version+'"><h2>More ways forward</h2><p>Your interests come first. Pay helps you compare options; it does not erase a match.</p>'+goal+alternatives+college+(compact?'<details class="more-info"><summary>Compare all five education routes</summary>'+tiers+'</details>':tiers)+'<details class="more-info"><summary>More info · how these options are chosen</summary><p>We look for shared work, related career fields, your six interest scores and the task choices you have actually answered. A related idea is not a confirmed match. A different role can need different interests, responsibilities and preparation.</p><p>Your original career results do not change. Education and salary do not boost the interest score. College can broaden access to roles; a degree alone does not guarantee higher pay. Community college and apprenticeships can also be strong routes.</p><p>Income comparisons use the same Austin budget, taxes, savings and entered loan payments. Unchosen borrowing is not assumed. Buying a home still needs upfront cash. Later salary stages are illustrations, not promised raises.</p><p><a href="https://www.bls.gov/emp/tables/education-summary.htm" target="_blank" rel="noopener">BLS education and occupations ↗</a> · <a href="https://www.apprenticeship.gov/career-seekers" target="_blank" rel="noopener">Apprenticeship routes ↗</a></p></details></section>';
}
